# Let me re-analyze the demo structure
demo_input = [[int(x) for x in line.split()] for line in demo_input_str.strip().split('\n')]

# Check all columns
for c in range(len(demo_input[0])):
    values = set(demo_input[r][c] for r in range(len(demo_input)))
    if len(values) == 1:
        print(f"Column {c}: all {list(values)[0]}")

# So cols 2 and 5 are separators, but what about col 7?
for c in range(8):
    if all(demo_input[r][c] == 0 for r in range(len(demo_input))):
        print(f"Col {c} is all zeros (separator)")
    else:
        print(f"Col {c} values: set({set(demo_input[r][c] for r in range(min(3, len(demo_input))))}...)")

# Correct row ranges: (0,5), (6,11), (12,17), (18,23)
# Correct col ranges: (0,2), (3,5), (6,8)

row_ranges = [(0, 5), (6, 11), (12, 17), (18, 23)]
col_ranges = [(0, 2), (3, 5), (6, 8)]

panels = []
for r_start, r_end in row_ranges:
    for c_start, c_end in col_ranges:
        panel = [row[c_start:c_end] for row in demo_input[r_start:r_end]]
        panels.append(panel)

print(f"Total panels: {len(panels)}")
print()

# Count 8s in each panel
for i, panel in enumerate(panels):
    r8 = sum(sum(r.count(8) for r in panel) for panel in [panel])
    print(f"Panel {i}: shape={len(panel)}x{len(panel[0])}, 8s={r8}")

    if r8 > 0:
        for r_idx, row in enumerate(panel):
            for c_idx, val in enumerate(row):
                if val == 8:
                    print(f"  8 at local ({r_idx}, {c_idx})")
    print()
